import {courses,lessons,terms,projects} from './content-et.js';
import {countries,countryNotes} from './countries-et.js';
import {escapeHTML as E,shuffle,populationChange,energyMix,cleanProgress} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='geo-expedition-v1';let state;try{state=cleanProgress(JSON.parse(localStorage.getItem(KEY))||{});}catch{state=cleanProgress({});}
let quiz=null,flash=null,mapMode='explore',mapRegion='world',mapTarget=null,mapSelected='EST',mapAnswered=false,world=null,labType='climate',searchCourse=0;
let saveTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(saveTimer);saveTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast("Brauser ei salvestanud edenemist. Ekspordi see jaotises „Edenemine”.");}}
function activity(xp=0){state.xp+=xp;const d=new Date().toLocaleDateString('sv-SE');if(!state.days.includes(d))state.days.push(d);save();}
function pct(list){return Math.round(list.filter(l=>state.done.includes(l.id)).length/list.length*100)||0;}
function heading(kicker,title,desc){return `<div class="page-intro"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>`;}
const nav=[['home','⌂',"Ülevaade","Avaleht"],['courses','▤',"Minu kursused","Kursused"],['atlas','◎',"Interaktiivne atlas","Atlas"],['practice','✧',"Harjutused","Harjutamine"],['labs','⚗',"Labor","Labor"],['glossary','Aa',"Sõnastik","Sõnastik"],['projects','◇',"Uurimistööd","Projektid"],['progress','↗',"Minu edenemine","Edenemine"]];
function navRender(route){$('#nav').innerHTML=nav.map(([id,icon,label,short])=>`<a class="nav-item ${(route===id||id==='courses'&&['course','lesson'].includes(route))?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''} title="${label}"><span class="nav-icon">${icon}</span><span>${label}</span><span class="mobile-label">${short}</span></a>`).join('');$('#breadcrumb').textContent=nav.find(n=>n[0]===route)?.[2]||(['course','lesson'].includes(route)?"Minu kursused / Õppimine":"GEO / Avastusretk");}
function globe(){return `<svg viewBox="0 0 430 380" aria-hidden="true"><defs><radialGradient id="ocean"><stop stop-color="#6d9780"/><stop offset="1" stop-color="#355f50"/></radialGradient><clipPath id="sphere"><circle cx="226" cy="186" r="132"/></clipPath></defs><g transform="rotate(-18 226 186)"><ellipse cx="226" cy="186" rx="194" ry="69" fill="none" stroke="#8fad7555"/><ellipse cx="226" cy="186" rx="161" ry="164" fill="none" stroke="#7f9e6530" stroke-dasharray="3 6"/><circle cx="226" cy="186" r="133" fill="url(#ocean)" stroke="#aac39377"/><g clip-path="url(#sphere)" fill="#c7d698"><path d="M104 89l49-26 46 11 7 25-25 13-4 21 16 13-23 28-12 20-28-8-16-30-28-9zM175 194l26 1 24 26 7 33-25 56-17 19-7-45-12-25 10-26zM235 73l39 2 32 22 50 7 8 21-30 12 11 20-32 4-14 23-28-9-13-35-19 9-18-13 8-16-18-10zM244 164l34 13 19 39-22 45-19 13-18-40-18-24 3-31zM317 256l33-12 35 18-15 24-31 2-25-17z"/><path d="M223 128l-11 13 8 10 10-7-1-13zM300 225l6 28-5 12-5-13z"/></g><g fill="none" stroke="#d8e8c021" clip-path="url(#sphere)"><ellipse cx="226" cy="186" rx="62" ry="132"/><ellipse cx="226" cy="186" rx="109" ry="132"/><path d="M94 186h264M108 127h236M107 246h238M226 54v264"/></g><ellipse cx="226" cy="186" rx="194" ry="69" fill="none" stroke="#d0e28b88" stroke-dasharray="310 600"/></g><circle cx="249" cy="126" r="17" fill="#d9ef8240"/><circle cx="249" cy="126" r="6" fill="#e8f4b1" stroke="#fff"/><path d="M254 120l42-34h57" fill="none" stroke="#c8d8aa"/><text x="306" y="79" fill="#e6efd7" font-size="10" font-family="sans-serif" letter-spacing="1">59°N · 25°E</text><circle cx="61" cy="233" r="5" fill="#e4edbf"/><path d="M73 45v12m-6-6h12M363 297v12m-6-6h12" stroke="#b9cd92"/></svg>`;}
function cover(c){if(c.id===1)return `<svg viewBox="0 0 270 145" aria-hidden="true"><circle cx="200" cy="40" r="22" fill="#edf1d9"/><path d="M0 145L93 22l67 90 47-68 63 101" fill="#839e73"/><path d="M29 145l84-106 69 106" fill="#aec196"/><path d="M75 62l18-40 27 42-25-11z" fill="#f3f4e2"/><path d="M102 145l54-89 64 89" fill="#577658"/><path d="M144 78l12-22 17 25-16-7z" fill="#e4ecd6"/><path d="M0 130q72-24 140 5t130-8v18H0" fill="#446b4f"/></svg>`;if(c.id===2)return `<svg viewBox="0 0 270 145" aria-hidden="true"><circle cx="202" cy="34" r="22" fill="#f0f4ef"/><path d="M10 145V76h30v69M48 145V51h36v94M92 145V27h36v118M139 145V68h33v77M183 145V45h42v100M238 145V91h32v54" fill="#83a1a6"/><path d="M15 145V100h34v45M60 145V84h50v61M125 145V59h39v86M179 145V102h48v43" fill="#4f777c"/><g fill="#d9e5d3"><path d="M100 40h7v9h-7zm12 0h7v9h-7zm-12 17h7v9h-7zm12 0h7v9h-7zM136 71h7v9h-7zm12 0h7v9h-7zm-12 17h7v9h-7zm12 0h7v9h-7z"/></g><path d="M0 144h270" stroke="#345958" stroke-width="8"/></svg>`;return `<svg viewBox="0 0 270 145" aria-hidden="true"><circle cx="204" cy="39" r="25" fill="#e6c078"/><path d="M0 122q81-53 142-9t128 4v28H0" fill="#a2ad7b"/><path d="M0 139q89-36 151-4t119-9v19H0" fill="#667d52"/><g stroke="#faf4da" stroke-width="4"><path d="M98 140V61M98 61L68 42M98 61l25-25M98 61l7 37M171 143V89M171 89l-24-16M171 89l22-22M171 89l6 29"/></g><g fill="#496b4b"><path d="M22 128l14-32 14 32zM44 132l16-40 16 40zM233 133l14-30 14 30z"/></g></svg>`;}
function courseCard(c){const ls=lessons.filter(l=>l.course===c.id),p=pct(ls);return `<a class="course-card" href="#course/${c.id}"><div class="course-cover ${c.color}"><span class="course-no">KURSUS 0${c.id}</span>${cover(c)}</div><div class="course-content"><div class="eyebrow">${c.tag}</div><h3>${c.title}</h3><p>${c.description}</p><div class="course-meta"><span>▤ ${ls.length} õppetundi</span><span>◷ ${c.hours} õppekava tundi</span></div><div class="progress-track"><span style="width:${p}%"></span></div><div class="course-foot"><span>${p?"Õpitud":"Kõik algab uudishimust"}</span><span>${p}% →</span></div></div></a>`;}
function home(){const next=lessons.find(l=>!state.done.includes(l.id))||lessons[0];return `<div class="welcome"><div><h1>Maailm ootab sinu avastusi <span style="color:#a2b483">✳</span></h1><p>Uuri, esita küsimusi ja leia seoseid.</p></div><span class="pill"><i class="dot"></i> Sinu tempo. Sinu teekond.</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">GEOGRAAFIA · GÜMNAASIUM · EESTI</div><h2>Maailm muutub<br><em>arusaadavamaks.</em></h2><p>Maa sügavustest tuleviku linnadeni.<br>Õpi geograafiat uurides ja avastades.</p><a href="#lesson/${next.id}" class="btn lime">${state.done.length?"Jätka uurimist":"Alusta avastusretke"} <span>↗</span></a></div><div class="hero-art">${globe()}</div><div class="hero-tag">ÜKS PLANEET. TUHANDED SEOSED.</div></section><div class="stat-row"><div class="stat"><i class="stat-icon">▤</i><div><b>3</b><span>õppekava kursust</span></div></div><div class="stat"><i class="stat-icon">◎</i><div><b>${lessons.length}</b><span>õppetundi koos harjutustega</span></div></div><div class="stat"><i class="stat-icon">⚗</i><div><b>5</b><span>interaktiivset laborit</span></div></div><div class="stat"><i class="stat-icon">✧</i><div><b>${state.xp}</b><span>avastuspunkti</span></div></div></div><div class="section-head"><h2>Kolm kursust. Terve planeet.</h2><a href="#courses">Kogu õppekava ↗</a></div><section class="course-grid">${courses.map(courseCard).join('')}</section><div class="section-head"><h2>Avasta õpikust kaugemale</h2><a href="#practice">Kõik harjutused ↗</a></div><div class="split"><a href="#atlas" class="card atlas-promo"><span class="big-orbit" aria-hidden="true">◎</span><div class="mini-label">INTERAKTIIVNE ATLAS</div><h3>Kus see kaardil asub?</h3><p>Avasta riike ja pealinnu ning kontrolli oma ruumilist mõtlemist.</p><span class="btn small secondary">Uuri kaarti ↗</span></a><div class="card challenge-card"><div class="mini-label">MÕTLEMISKÜSIMUS</div><h3>Miks on Läänemeri<br>vähem soolane kui ookean?</h3><p>Vihje: mõtle jõgedele, sademetele ja veevahetusele.</p><a href="#lesson/12" class="btn small secondary">Leia selgitus →</a></div></div><div class="section-head"><h2>Sinu uurimisvahendid</h2></div><div class="course-grid"><a class="card" href="#labs"><div class="mini-label">KATSED</div><h3>Mis juhtuks, kui…</h3><p class="caption">Muuda energiabilanssi, rahvastikuvooge või veekasutust. Jälgi tagajärgi.</p></a><a class="card" href="#glossary"><div class="mini-label">RU / ET</div><h3>Kasuta teaduse keelt</h3><p class="caption">${terms.length} vene- ja eestikeelset mõistet koos selgete määratlustega.</p></a><a class="card" href="#projects"><div class="mini-label">9 UURIMISTÖÖD</div><h3>Küsimusest järelduseni</h3><p class="caption">Geograafilised uurimisülesanded, töövihik ja enesekontrolli kriteeriumid.</p></a></div>`;}
function lessonRow(l){return `<a class="lesson-row" href="#lesson/${l.id}"><span class="num ${state.done.includes(l.id)?'done':''}">${state.done.includes(l.id)?'✓':String(l.id).padStart(2,'0')}</span><div><strong>${l.title}</strong><small>${l.et}</small></div><span class="time">${l.minutes} min →</span></a>`;}
function coursePage(id){const c=courses.find(c=>c.id===+id);if(!c)return missing();return `${heading("KURSUS 0"+c.id+' / '+c.et,c.title,c.description)}<div class="pill">${lessons.filter(l=>l.course===c.id).length} õppeteemat · ${c.hours} tundi algses õppekavas · õpitud ${pct(lessons.filter(l=>l.course===c.id))}%</div>${c.modules.map((m,i)=>`<h2 class="module-head">${String(i+1).padStart(2,'0')} / ${m}</h2>${lessons.filter(l=>l.course===c.id&&l.module===i).map(lessonRow).join('')}`).join('')}<div class="action-row"><button class="btn" data-action="start-quiz" data-course="${c.id}">Kontrolli kursuse teadmisi →</button><a class="btn secondary" href="#projects">Uurimistöö</a></div>`;}
function lessonPage(id){const l=lessons.find(l=>l.id===+id);if(!l)return missing();return `${heading(`KURSUS ${l.course} / ${courses[l.course-1].modules[l.module]}`,l.title,l.et+' · '+l.minutes+" minutit lugemiseks ja harjutamiseks")}<div class="reading-grid"><article class="card lesson-article"><div class="mini-label">MÕISTA PÕHIMÕTTEID</div>${l.paragraphs.map(p=>`<p>${p}</p>`).join('')}<div class="note"><strong>Seos tegeliku maailmaga</strong>${l.example}</div><h2>Kontrolli oma arusaamist</h2><div id="lesson-check"><p>${l.question.prompt}</p>${shuffle(l.question.options.map((s,i)=>({s,i}))).map(o=>`<button class="answer" data-action="lesson-answer" data-id="${l.id}" data-value="${o.i}">${o.s}</button>`).join('')}<div id="lesson-feedback" aria-live="polite"></div></div><details><summary>Selgita oma sõnadega</summary><p>Kirjelda õppetunnis käsitletud põhjuse ja tagajärje seost. Too oma näide ja nimeta tingimus, mille korral järeldus võiks muutuda. Võrdle selgitust tekstiga. Vabavastust siin automaatselt ei hinnata.</p></details><label for="lesson-note">Minu märkmed ja küsimused</label><textarea id="lesson-note" data-note="l${l.id}" placeholder="Mis sai selgemaks? Mida tuleks veel kontrollida?">${E(state.notes['l'+l.id]||'')}</textarea><small class="subtle">Märkmed salvestatakse sellesse brauserisse.</small><div class="action-row"><button class="btn" data-action="complete" data-id="${l.id}" ${state.done.includes(l.id)?'disabled':''}>${state.done.includes(l.id)?"✓ Õppetund läbitud":"Märgi õppetund õpituks +20"}</button><a class="btn secondary" href="#${l.id<lessons.length?'lesson/'+(l.id+1):'progress'}">${l.id<lessons.length?"Järgmine õppetund →":"Minu edenemine →"}</a></div></article><aside><div class="card sticky"><div class="mini-label">GEOGRAAFIA KEEL</div>${l.terms.map(t=>`<div class="term-chip"><strong>${t.ru}</strong><small>${t.et}</small><p>${t.definition}</p></div>`).join('')}<div class="action-row"><a href="#course/${l.course}" class="btn small secondary">← Kursuse õppekava juurde</a><a href="#glossary" class="btn small secondary">Kogu sõnastik</a></div><p class="caption">Läbimise enesehinnang ja testitulemused salvestatakse eraldi: lugemine üksi ei tõenda teema valdamist.</p></div></aside></div>`;}
function practicePage(){return `${heading("ÕPI TEGUTSEDES","Põnev harjutamine","Vead aitavad märgata, mida veel uurida. Iga vastuse järel näed selgitust.")}<div class="course-grid">${courses.map(c=>`<div class="card"><div class="mini-label">KURSUS ${c.id}</div><h3>${c.title}</h3><p class="caption">10 juhuslikku küsimust kursuse sisu ja mõistete kohta. Ajapiiranguta.</p><button class="btn" data-action="start-quiz" data-course="${c.id}">Alusta testi →</button></div>`).join('')}</div><div class="section-head"><h2>Vali harjutuse tüüp</h2></div><div class="course-grid"><div class="card"><div class="mini-label">KÕIK KOLM KURSUST</div><h3>Suur avastusretk</h3><p class="caption">20 küsimust ühes testis. Kokkuvõte sisaldab selgitusi ja linke õppetundidele.</p><button class="btn secondary" data-action="start-quiz" data-course="0">Segatest</button></div><div class="card"><div class="mini-label">HAJUTATUD KORDAMINE</div><h3>Mõistekaardid</h3><p class="caption">Meenuta määratlust enne kaardi pööramist. Keerulised mõisted tulevad selle harjutuskorra jooksul uuesti.</p><button class="btn secondary" data-action="flash-start">Õpi mõistekaartidega</button></div><div class="card"><div class="mini-label">POLIITILINE KAART</div><h3>Riigid ja pealinnad</h3><p class="caption">Euroopa ja õppekavas nimetatud riigid. Vaidlusaluste ning erijuhtumite selgitused leiad atlasest.</p><button class="btn secondary" data-action="capital-quiz">Harjuta pealinnu</button></div><div class="card"><div class="mini-label">SINU ARENGUKOHAD</div><h3>Vigade analüüs</h3><p class="caption">${state.mistakes.length} teemat kordamiseks. Loe selgitusi ja kontrolli end uuesti.</p><button class="btn secondary" data-action="mistake-quiz" ${state.mistakes.length?'':'disabled'}>Korda keerulisi teemasid</button></div><a class="card" href="#atlas"><div class="mini-label">RUUMILINE MÕTLEMINE</div><h3>Leia riik</h3><p class="caption">Kaardiharjutus näitab õiget asukohta ja võimaldab uusi katseid.</p><span class="btn secondary">Ava atlas →</span></a><a class="card" href="#labs"><div class="mini-label">PÕHJUSED JA TAGAJÄRJED</div><h3>Muuda tingimusi</h3><p class="caption">Viis mudelit iseseisvateks katseteks.</p><span class="btn secondary">Laborisse →</span></a></div>`;}
function questionBank(course){const ls=lessons.filter(l=>!course||l.course===course);return ls.flatMap(l=>[{...l.question,lesson:l.id},...l.terms.map(t=>({prompt:`Milline mõiste vastab määratlusele: „${t.definition}”?`,options:[t.ru,...shuffle(terms.filter(x=>x.ru!==t.ru)).slice(0,2).map(x=>x.ru)],correct:0,explanation:`${t.ru} (${t.et}) — ${t.definition.toLowerCase()}.`,lesson:l.id}))]);}
function beginQuiz(course,errors=false){const bank=questionBank(course).filter(q=>!errors||state.mistakes.includes(q.lesson));quiz={items:shuffle(bank).slice(0,errors?Math.min(10,bank.length):course?10:20).map(q=>({...q,choices:shuffle(q.options.map((s,i)=>({s,correct:i===q.correct})))})),index:0,results:[],answered:false,title:errors?"Vigade parandamine":course?courses[course-1].title:"Suur avastusretk"};location.hash='quiz';render();}
function quizPage(){if(!quiz)return practicePage();if(quiz.index>=quiz.items.length){const score=quiz.results.filter(r=>r.ok).length;return `${heading("AVASTUSRETK LÕPETATUD","Nüüd tead rohkem",quiz.title)}<div class="card quiz-container"><div class="result-score">${score}<span style="font-size:25px;color:#8c9785"> / ${quiz.items.length}</span></div><h2>${score===quiz.items.length?"Selle küsimustekogumiga said väga hästi hakkama!":"Järgmise sammu jaoks on alus olemas."}</h2><p>See on harjutustulemus, mitte ametlik koolihinne. Vaata selgitused läbi ja rakenda teadmisi uurimistöös.</p>${quiz.results.filter(r=>!r.ok).map(r=>`<div class="note"><strong>${r.q.prompt}</strong>${r.q.explanation}${r.q.lesson?`<p><a href="#lesson/${r.q.lesson}"><u>Tagasi õppetundi →</u></a></p>`:''}</div>`).join('')}<div class="action-row"><a href="#practice" class="btn">Teine harjutus</a><a href="#progress" class="btn secondary">Vaata edenemist</a></div></div>`;}
const q=quiz.items[quiz.index];return `<div class="quiz-container">${heading("HARJUTUS",quiz.title,"Mõtle vastus esmalt läbi. Selgitus ilmub pärast valikut.")}<div class="quiz-head"><span>Küsimus ${quiz.index+1} / ${quiz.items.length}</span><span>${quiz.results.filter(r=>r.ok).length} õiget vastust</span></div><div class="progress-track"><span style="width:${quiz.index/quiz.items.length*100}%"></span></div><div class="card" style="margin-top:22px"><h2>${q.prompt}</h2>${q.choices.map((o,i)=>`<button class="answer" data-action="quiz-answer" data-value="${i}">${o.s}</button>`).join('')}<div id="quiz-feedback" aria-live="polite"></div></div></div>`;}
function flashPage(){if(!flash)return practicePage();if(!flash.queue.length)return heading("KORDAMINE","Mõistekaardid läbitud","Kordasid 12 mõistet. Kontrolli, kas oskad neid selgituses kasutada.")+"<a class=\"btn\" href=\"#practice\">Harjutuste juurde →</a>";const t=flash.queue[0];return `<div class="quiz-container">${heading('RU / ET',"Meenuta. Selgita. Kontrolli.","Proovi määratlus sõnastada enne kaardi pööramist.")}<div class="quiz-head"><span>Jäänud ${flash.queue.length} kaarti</span><span>Kindlalt: ${flash.known}</span></div><button class="card flashcard" data-action="flash-flip"><small class="mini-label">${flash.flipped?"MÄÄRATLUS":"MIDA SEE TÄHENDAB?"}</small><strong>${flash.flipped?t.definition:t.ru}</strong><span>${t.et}</span><small style="margin-top:30px">${flash.flipped?"Hinda, kui täpselt meenutasid":"Vajuta kaardi pööramiseks ↻"}</small></button>${flash.flipped?`<div class="action-row"><button class="btn secondary" data-action="flash-again">Korda hiljem</button><button class="btn" data-action="flash-known">Tean +5</button></div>`:''}</div>`;}
function glossaryPage(){return `${heading("EESTI + VENE","Uurija sõnastik",`${terms.length} mõistet maailma selgitamiseks. Otsi eesti või vene keeles.`)}<label class="sr-only" for="term-search">Mõiste otsing</label><input id="term-search" type="search" placeholder="Näiteks: litosfäär, ränne, energia…"><div id="term-results" class="glossary-grid">${termCards(terms)}</div>`;}
function termCards(ts){return ts.length?ts.map(t=>`<a class="card" href="#lesson/${t.lesson}"><small>KURSUS ${t.course}</small><h3>${t.ru}</h3><small>${t.et}</small><p>${t.definition}</p><small>Ava õppetunni kontekstis →</small></a>`).join(''):"<p class=\"empty\">Midagi ei leitud. Proovi lühemat sõna.</p>";}
function projectsPage(){return `${heading("KÜSIMUSEST TÕENDITENI","Sinu uurimistöökoda","Üheksa tööd õppekava praktilise osa järgi. Kogu andmeid, võrdle selgitusi ja sõnasta põhjendatud järeldus.")}<div class="project-grid">${projects.map((p,i)=>`<div class="card"><div class="mini-label">KURSUS ${p.course} · UURIMISTÖÖ ${i+1}</div><h3>${p.title}</h3><p>${p.brief}</p><a class="btn secondary" href="#project/${i}">${state.notes['p'+i]?"Jätka tööd":"Ava ülesanne"} →</a></div>`).join('')}</div>`;}
function projectPage(id){const p=projects[+id];if(!p)return missing();return `${heading("PRAKTILINE TÖÖ / KURSUS "+p.course,p.title,p.brief)}<div class="reading-grid"><div class="card"><h2>Uurimistöö etapid</h2><ol class="checklist">${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="note"><strong>Head järeldust saab kontrollida</strong>Märgi andmete allikas, kuupäev ja ühikud. Erista vaatlus selgitusest. Nimeta piirang või alternatiivne põhjus.</div><label for="project-note">Töövihik</label><textarea id="project-note" style="min-height:330px" data-note="p${id}" placeholder="Uurimisküsimus:\nAndmed ja allikad (kuupäevadega):\nVõrdlus:\nSelgitus:\nJäreldus ja piirangud:">${E(state.notes['p'+id]||'')}</textarea><p class="caption">Salvestatakse brauserisse. Ülekandmiseks kasuta eksporti. Esseesid automaatselt ei hinnata.</p><div class="action-row"><button class="btn" data-action="download-project" data-id="${id}">Laadi töö alla .txt</button><a class="btn secondary" href="#projects">Teised uurimistööd</a></div></div><aside class="card" style="height:fit-content"><h3>Enesekontrolli kriteeriumid</h3>${["Uurimisküsimus on konkreetne","Andmed on võrreldavad ja allikas on märgitud","Põhjuslik seos on selgitatud","Esitatud on näide ja vastuargument","Järeldus vastab küsimusele"].map((s,i)=>`<p><label><input type="checkbox"> ${s}</label></p>`).join('')}<small class="subtle">Kontrollnimekiri selle vaatamise jaoks; töö tekst salvestatakse eraldi.</small></aside></div>`;}
function progressPage(){const p=pct(lessons);return `${heading("SINU AVASTUSRETK","Iga samm on tähtis","Edenemine salvestatakse ainult sellesse brauserisse. Teise seadmesse viimiseks ekspordi varukoopia.")}<div class="two-col"><div class="card" style="text-align:center"><div class="mini-label">ÕPITUD ÕPPETUNNID</div><div class="progress-circle" style="--percent:${p}%"><span>${p}%</span></div><p>${state.done.length} / ${lessons.length} õppetundi on märgitud õpituks</p><small class="subtle">Need on läbimise märked, mitte kõigi oskuste mõõtmine.</small></div><div class="card"><div class="metric-grid"><div class="metric"><strong>${state.xp}</strong><span>punkti</span></div><div class="metric"><strong>${state.quizRuns}</strong><span>testi lõpetatud</span></div><div class="metric"><strong>${state.days.length}</strong><span>õppepäeva</span></div></div><p>Õigeid vastuseid: <strong>${state.correct} / ${state.answers}</strong> ${state.answers?'('+Math.round(state.correct/state.answers*100)+'%)':''}</p><p>Leitud riike: <strong>${state.mapCorrect}</strong> · Korratud kaarte: <strong>${state.cards}</strong></p><p>Proovitud laboreid: <strong>${state.labs.length} / 5</strong></p></div></div><div class="section-head"><h2>Avastuste kogu</h2></div><div class="badge-grid">${[['✧',"Esimene samm",state.done.length>=1,"Läbi üks õppetund"],['◎',"Kartograaf",state.mapCorrect>=10,"Leia 10 riiki"],['⚗',"Katsetaja",state.labs.length===5,"Proovi kõiki 5 laborit"],['▤',"Uurija",state.done.length===lessons.length,"Läbi kõik õppetunnid"]].map(([i,t,ok,d])=>`<div class="badge ${ok?'earned':''}"><b>${i}</b><strong>${t}</strong><small>${ok?"✓ Avatud":d}</small></div>`).join('')}</div><div class="section-head"><h2>Edenemine kursuste kaupa</h2></div><div class="course-grid">${courses.map(courseCard).join('')}</div><div class="card" style="margin-top:25px"><h3>Sinu andmed on sinu kontrolli all</h3><div class="action-row"><button class="btn" data-action="export">Ekspordi edenemine</button><label class="btn secondary" for="import-file">Impordi varukoopia</label><input type="file" id="import-file" accept="application/json,.json" hidden><button class="btn secondary danger" data-action="reset">Kustuta edenemine</button></div><div id="reset-confirm"></div><p class="caption">Import asendab praeguse ajaloo. Märkmeid serverisse ei saadeta. Brauseri andmete kustutamine eemaldab kohaliku edenemise.</p></div>`;}
function aboutPage(){return `${heading("LÄBIPAISTVUS JA ALLIKAD","GEO alus","Õppeplatvorm iseseisvaks õppimiseks kolme esitatud Eesti gümnaasiumi ainekava järgi.")}<div class="card source-links"><h2>Vastavus algfailidele</h2><div class="table-wrap"><table><thead><tr><th>Fail</th><th>Kursus</th><th>Teemaplokid</th></tr></thead><tbody><tr><td>1. kursuse ainekava (.docx)</td><td>Maa kui süsteem</td><td>Sissejuhatus · litosfäär · atmosfäär · hüdrosfäär · biosfäär</td></tr><tr><td>2. kursuse ainekava (.docx)</td><td>Rahvastik ja majandus</td><td>Uurimismeetodid · areng · rahvastik · asustus · majandus</td></tr><tr><td>3. kursuse ainekava (.docx)</td><td>Loodusvarad ja nende kasutamine</td><td>Põllumajandus · vesi · mets · energeetika</td></tr></tbody></table></div><div class="note"><strong>Kuidas mõista õppekava mahtu</strong>Igas failis on märgitud 35 tundi. Kolmandas annavad teematunnid kokku 31: 9 + 8 + 5 + 9. Ülejäänud neli tundi võib kasutada kordamiseks ja uurimistööks. See on platvormi ettepanek, mitte algdokumendi muudatus. GEO 42 õppetundi on õppeteemad, mitte 42 koolitundi.</div><p>Tekstid ja ülesanded on koostatud selle platvormi jaoks. Need hõlmavad teemaplokke, kuid ei asenda terviklikku õpikut, tööd algandmetega ega õpetaja hindamist. Avatud uurimistöid kontrollitakse kriteeriumide alusel iseseisvalt. Kursuste numeratsioon järgib failinimesid ka siis, kui õpiku nimetus bibliograafias erineb.</p><h2>Kontrollitavad teadusallikad</h2><ul><li><a href="https://www.usgs.gov/faqs/are-tectonic-plates-floating-magma" target="_blank" rel="noopener">USGS: laamad ja vahevöö olek</a></li><li><a href="https://www.ipcc.ch/report/ar6/syr/summary-for-policymakers/" target="_blank" rel="noopener">IPCC AR6: tänapäevase kliimamuutuse põhjused</a></li><li><a href="https://helcom.fi/baltic-sea-trends/eutrophication/" target="_blank" rel="noopener">HELCOM: Läänemere eutrofeerumine</a></li><li><a href="https://andmed.stat.ee/en/stat" target="_blank" rel="noopener">Statistics Estonia: uurimistöö andmed</a></li><li><a href="https://hdr.undp.org/" target="_blank" rel="noopener">UNDP: inimarengu näitajad</a></li><li><a href="https://geoportaal.maaamet.ee/" target="_blank" rel="noopener">Eesti geoportaal: kaardid ja ruumiandmed</a></li></ul><h2>Mudelid ja kaart</h2><p>Laborite arvulised stsenaariumid on õppeotstarbelised, mitte hetke statistika ega prognoos. Lihtsustused on kirjeldatud mudeli kõrval. Kaardi alus: <a href="https://github.com/johan/world.geo.json" target="_blank" rel="noopener">world.geo.json</a>, algandmed pärinevad Natural Earthist. Kaart on üldistatud ega ole mõeldud piiride õiguslikuks määramiseks. Väikeriike tähistavad punktid; poliitilised eripärad on selgitatud kaartidel.</p><p>Sisu on koostatud esitatud failide põhjal 2026. aasta oktoobris. Tänapäevaste näitajate ja muutuvate halduslike staatuste puhul kontrolli alati algallika kuupäeva.</p><h2>Kuidas salvestamine toimib</h2><p>Sisselogimine ei ole vajalik. Edenemine, tulemused ja märkmed asuvad brauseri kohalikus salvestusruumis. Seadmete vahel automaatset sünkroonimist ei toimu; kasutada saab eksporti ja importi. Kirjatüübid võivad laadida Google Fontsist; õppematerjalid ja kaart asuvad saidiga koos.</p></div>`;}
function searchPage(){return `${heading("OTSING","Leia järgmine õppeteema","Otsi pealkirjadest, õppetundide tekstidest ning vene- ja eestikeelsetest mõistetest.")}<label for="global-search" class="sr-only">Otsi platvormilt</label><input id="global-search" type="search" placeholder="Näiteks: vesi, rahvastik, Läänemeri…" autofocus><div id="search-results"><p class="subtle">Alusta otsingusõna sisestamist.</p></div>`;}
function missing(){return heading('GEO',"Seda lehte ei ole","Vali kursus või naase ülevaatesse.")+"<a class=\"btn\" href=\"#home\">Avalehele</a>";}
function atlasPage(){return `${heading("VAATA MAAILMA AVARAMALT","Interaktiivne atlas","Uuri õppekavas nimetatud riike. Suurenda Euroopat, ava riigi kaart või vali harjutusrežiim.")}<div class="tabs"><button class="tab ${mapMode==='explore'?'active':''}" data-action="map-mode" data-value="explore">Uuri</button><button class="tab ${mapMode==='quiz'?'active':''}" data-action="map-mode" data-value="quiz">Leia riik</button><button class="tab ${mapRegion==='world'?'active':''}" data-action="map-region" data-value="world">Kogu maailm</button><button class="tab ${mapRegion==='europe'?'active':''}" data-action="map-region" data-value="europe">Euroopa suurendus</button></div>${mapMode==='quiz'?`<div class="map-task"><p>Leia kaardilt: <strong>${mapTarget?.name||"Eesti"}</strong><br><small id="map-feedback" aria-live="polite">Vajuta riigi territooriumile või punktile. Nimed on vastamiseni peidetud.</small></p><button class="btn small secondary" data-action="map-next">${mapAnswered?"Järgmine →":"Jäta vahele →"}</button></div>`:''}<div class="map-layout"><div><div class="map-shell"><svg id="world-map" viewBox="${mapRegion==='world'?'0 0 720 360':'306 32 155 91'}" aria-label="Maailma poliitiline kaart. Riike saab valida Enter-klahviga." role="group"></svg><div class="map-controls"><button class="btn small secondary" data-action="map-region" data-value="europe">＋ Euroopa</button><button class="btn small secondary" data-action="map-region" data-value="world">− Kogu maailm</button></div></div><p class="caption">Lihtsustatud võrdvaheline projektsioon: pindalad ja kujud moonduvad. Punktid tähistavad õppeotstarbelisi asukohti, mitte pealinnu. Alus: Natural Earth / world.geo.json.</p></div><aside class="card map-info" id="map-info">${mapMode==='explore'?countryInfo(mapSelected):"<h3>Uuri kuju ja naabreid</h3><p class=\"caption\">Harjutusrežiimis on loend peidetud. Väikeriikide leidmiseks suurenda Euroopat.</p><p class=\"caption\">Euroopa ülesannetes on ka punktidega tähistatud väikeriigid.</p>"}</aside></div>`;}
function countryInfo(id){const c=countries.find(x=>x.id===id);if(!c)return "<h3>Vali riik</h3>";return `<div class="mini-label">${c.region}</div><h2>${c.name}</h2><div class="term-chip"><small>PEALINN</small><strong>${c.capital}</strong></div>${countryNotes[id]?`<p class="caption">${countryNotes[id]}</p>`:''}<label for="country-search">Riigi kiirotsing</label><input id="country-search" type="search" placeholder="Nimi…"><div class="country-list" id="country-results">${countryButtons(countries)}</div>`;}
function countryButtons(cs){return cs.map(c=>`<button class="country-button" data-action="country-select" data-id="${c.id}">${c.name}</button>`).join('');}
const projectPoint=([x,y])=>[(x+180)*2,(90-y)*2];
function pathGeo(geometry){const ps=geometry.type==='Polygon'?[geometry.coordinates]:geometry.type==='MultiPolygon'?geometry.coordinates:[];return ps.flatMap(p=>p.map(r=>r.map((xy,i)=>{const [x,y]=projectPoint(xy);return `${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`;}).join('')+'Z')).join('');}
async function drawMap(){const svg=$('#world-map');if(!svg)return;try{if(!world){const r=await fetch('/world.json');if(!r.ok)throw Error();world=await r.json();}if(!svg.isConnected)return;const explore=mapMode==='explore';svg.innerHTML=`<rect x="0" y="0" width="720" height="360" fill="#e7efeb"/>${Array.from({length:11},(_,i)=>`<path d="M${i*72} 0v360" stroke="#d4e1db" stroke-width=".5"/>`).join('')}${Array.from({length:5},(_,i)=>`<path d="M0 ${(i+1)*60}h720" stroke="#d4e1db" stroke-width=".5"/>`).join('')}${world.features.map(f=>{const c=countries.find(c=>c.id===f.id);return `<path d="${pathGeo(f.geometry)}" fill-rule="evenodd" class="land ${explore&&mapSelected===f.id?'selected':''} ${mapAnswered&&mapTarget?.id===f.id?'target':''}" data-action="map-pick" data-id="${E(f.id)}" ${c?`tabindex="0" role="button" aria-label="${explore?E(c.name):"Riigi territoorium"}"`:''}>${explore?`<title>${E(c?.name||f.properties.name)}</title>`:''}</path>`;}).join('')}${countries.filter(c=>mapRegion==='world'||c.region.includes("Euroopa")).map(c=>{const [x,y]=projectPoint([c.lon,c.lat]);return `<circle cx="${x}" cy="${y}" r="${mapRegion==='europe'?.65:1.5}" class="map-dot ${mapAnswered&&mapTarget?.id===c.id?'target':''}" data-action="map-pick" data-id="${c.id}" tabindex="0" role="button" aria-label="${explore?c.name:"Riigi punkt"}">${explore?`<title>${c.name}</title>`:''}</circle>`;}).join('')}`;}catch{svg.outerHTML="<p class=\"empty\">Kaardi laadimine ebaõnnestus. Laadi leht uuesti. Riikide loend on paremal.</p>";}}
function nextMap(){const pool=countries.filter(c=>mapRegion==='world'?!['IDN'].includes(c.id):c.region==="Euroopa");mapTarget=shuffle(pool.filter(c=>c.id!==mapTarget?.id))[0];mapAnswered=false;}
const labNames={climate:"Kliimadiagramm",population:"Demograafia",energy:"Energiabilanss",water:"Veebilanss",plates:"Laamtektoonika"};
function labsPage(){return `${heading("MUUDA TINGIMUSI. JÄLGI SEOSEID.","Geograafialabor","Viis õppemudelit. Ennusta esmalt tulemust, siis muuda parameetreid ja selgita juhtunut.")}<div class="tabs">${Object.entries(labNames).map(([id,name])=>`<button class="tab ${labType===id?'active':''}" data-action="lab-tab" data-value="${id}">${name}</button>`).join('')}</div><div id="lab-content">${labHTML()}</div>`;}
function slider(id,label,min,max,value,unit=''){return `<label for="${id}">${label} <output id="${id}-value">${value}${unit}</output></label><input type="range" data-lab-input id="${id}" min="${min}" max="${max}" value="${value}" data-unit="${unit}">`;}
function labHTML(){if(labType==='climate')return `<div class="lab-layout"><div class="card"><div class="mini-label">KLIIMA ARVUDES</div><label for="climate-type">Õppemudeli kliimatüüp</label><select id="climate-type" data-lab-input><option value="maritime">Parasvöötme mereline</option><option value="continental">Parasvöötme mandriline</option><option value="tropical">Niiske ekvatoriaalne</option><option value="desert">Troopiline kõrbekliima</option><option value="mediterranean">Vahemereline</option></select>${slider('warming',"Temperatuuri nihe",-5,5,0,' °C')}<p class="caption">Võrdlemiseks loodud sünteetilised kuuandmed, mitte kindla linna vaatlused. Temperatuuri nihutamine ei modelleeri sademete muutust.</p><button class="btn small" data-action="lab-done">Salvesta katse +15</button></div><div class="card"><h3>Temperatuur ja sademed kuude kaupa</h3><div id="lab-output"></div><details><summary>Kuidas kliimadiagrammi lugeda?</summary><p>Oranž joon näitab temperatuuri (vasak skaala, °C), tulbad sademeid (parem skaala, mm). Leia maksimumide aastaaeg, temperatuuri amplituud ja aastane sademete summa. Tulba kõrgust ja temperatuuri ei saa otse võrrelda.</p></details></div></div>`;
if(labType==='population')return `<div class="lab-layout"><div class="card"><div class="mini-label">ÜKS TINGLIK AASTA</div>${slider('births',"Sündinud",0,3000,900)}${slider('deaths',"Surnud",0,3000,1100)}${slider('incoming',"Saabunud",0,3000,800)}${slider('outgoing',"Lahkunud",0,3000,300)}<button class="btn small" data-action="lab-done">Salvesta katse +15</button></div><div class="card"><h3>Rahvastik: mis mõjutab tulemust?</h3><p class="caption">Tinglik linn: aasta alguses 100 000 elanikku. Kõik vood on antud inimeste arvuna, mitte promillides.</p><div id="lab-output"></div><div class="note"><strong>Ülesanne</strong>Hoia loomulik iive negatiivsena, kuid saavuta rahvaarvu kasv. Mis põhjustab selle tulemuse?</div></div></div>`;
if(labType==='energy')return `<div class="lab-layout"><div class="card"><div class="mini-label">KOOSTA OMA ENERGIABILANSS</div>${slider('fossil',"Fossiilkütused",0,100,40)}${slider('wind',"Tuul",0,100,25)}${slider('solar',"Päike",0,100,15)}${slider('nuclear',"Tuumaenergia",0,100,20)}<p class="caption">Allikate osakaalud normeeritakse kokku 100%-ks. Need on toodangu, mitte paigaldatud võimsuse osakaalud.</p><button class="btn small" data-action="lab-done">Salvesta katse +15</button></div><div class="card"><h3>Heide ja muutlik tootmine</h3><div id="lab-output"></div><p class="caption">Õppemudeli olelusringi kordajad: 700 / 12 / 45 / 12 g CO₂-ekv/kWh vastavalt. Need on mudeli tinglikud ümardatud väärtused, mitte konkreetsete jaamade näitajad. Mudel ei hinda hinda, tunnipõhist töökindlust ega salvestusvajadust.</p><div class="note"><strong>Selgita kompromissi</strong>Vähenda keskmist süsinikumahukust. Milliseid lisaandmeid vajad süsteemi talvise töökindluse hindamiseks?</div></div></div>`;
if(labType==='water')return `<div class="lab-layout"><div class="card"><div class="mini-label">VALGLA AASTABILANSS</div>${slider('rain',"Sademed",0,1500,700," mm")}${slider('evap',"Auramine",0,1000,450," mm")}${slider('use',"Tagastamatu veevõtt",0,500,100," mm")}<button class="btn small" data-action="lab-done">Salvesta katse +15</button></div><div class="card"><h3>Kas saabuvast veest piisab?</h3><div id="lab-output"></div><p class="caption">Lihtsustatud valgla: väline sissevool puudub. Kui jääk P − E − W on mittenegatiivne, võib see muutumatu varu korral anda äravoolu. Negatiivne jääk tähendab varu kahanemist või määratud voogude jätkamise võimatust. Auramist ja veevõttu arvestatakse eraldi, topeltarvestuseta.</p><div class="note"><strong>Kontrolli kestlikkust</strong>Mis juhtub varuga, kui puudujääk kordub viis aastat? Miks ei tõenda suur varu veel veekasutuse kestlikkust?</div></div></div>`;
return `<div class="lab-layout"><div class="card"><div class="mini-label">KOLM PIIRITÜÜPI</div><label for="plate-type">Laamade vastastikmõju</label><select id="plate-type" data-lab-input><option value="divergent">Lahknemine</option><option value="convergent">Subduktsioon</option><option value="transform">Külgsuunaline nihkumine</option></select>${slider('plate-step',"Mudeli edenemine",0,100,30,'%')}<p class="caption">Skeem ei ole mõõtkavas. Liugur näitab protsessi kulgu, mitte tegelikku kiirust sentimeetrites aastas.</p><button class="btn small" data-action="lab-done">Salvesta katse +15</button></div><div class="card"><h3>Kuidas laamapiir muutub?</h3><div id="lab-output"></div><div class="note"><strong>Rakenda selgitust kaardil</strong>Seosta mudel Islandi, Andide ja San Andrease murranguga. Kus tekib maakoor ja kus see sukeldub?</div></div></div>`;}
const val=id=>Number($('#'+id)?.value||0);
function labUpdate(){const out=$('#lab-output');if(!out)return;$$('[data-lab-input][type=range]').forEach(el=>{const o=$('#'+el.id+'-value');if(o)o.textContent=el.value+(el.dataset.unit||'');});if(labType==='climate'){const data={maritime:[[-2,-2,1,6,12,16,18,17,12,7,3,0],[45,35,38,35,45,65,75,80,65,70,60,50]],continental:[[-18,-15,-6,5,14,20,23,20,12,3,-8,-15],[18,15,20,30,45,60,70,55,38,30,25,20]],tropical:[[26,26,27,27,27,26,26,26,26,26,26,26],[220,200,250,260,230,180,160,170,190,230,250,240]],desert:[[15,17,21,26,31,35,37,36,32,26,20,16],[5,4,4,2,1,0,0,0,0,1,3,5]],mediterranean:[[10,11,13,16,20,24,27,27,24,20,15,11],[80,65,50,40,25,10,3,5,25,60,85,95]]}[$('#climate-type').value];const ts=data[0].map(v=>v+val('warming')),rs=data[1],months=["J","V","M","A","M","J","J","A","S","O","N","D"];out.innerHTML=`<svg class="lab-chart" viewBox="0 0 620 310" role="img" aria-label="Õppemudeli kliimadiagramm"><text x="20" y="20" fill="#b37a49" font-size="12">°C</text><text x="578" y="20" fill="#6d9ca9" font-size="12">mm</text>${[-20,0,20,40].map(t=>{const y=270-(t+20)*3.5;return `<path d="M45 ${y}H575" stroke="#e1e7db"/><text x="12" y="${y+4}" font-size="11" fill="#778578">${t}</text>`;}).join('')}${[0,100,200,300].map(v=>`<text x="580" y="${274-v*.7}" font-size="11" fill="#778578">${v}</text>`).join('')}${rs.map((v,i)=>`<rect x="${57+i*43}" y="${270-v*.7}" width="24" height="${v*.7}" rx="3" fill="#a1bec4"/><text x="${64+i*43}" y="293" font-size="11" fill="#778578">${months[i]}</text>`).join('')}<polyline class="graph-line" points="${ts.map((t,i)=>`${69+i*43},${270-(t+20)*3.5}`).join(' ')}"/>${ts.map((t,i)=>`<circle cx="${69+i*43}" cy="${270-(t+20)*3.5}" r="3" fill="#d0915d"/>`).join('')}</svg><div class="metric-grid"><div class="metric"><strong>${(ts.reduce((a,b)=>a+b)/12).toFixed(1)}°</strong><span>aasta keskmine</span></div><div class="metric"><strong>${Math.max(...ts)-Math.min(...ts)}°</strong><span>aastane amplituud</span></div><div class="metric"><strong>${rs.reduce((a,b)=>a+b)}</strong><span>sademed, mm/a</span></div></div><details><summary>Andmetabel</summary><div class="table-wrap"><table><tr><th>Kuu</th>${months.map(m=>`<th>${m}</th>`).join('')}</tr><tr><td>°C</td>${ts.map(t=>`<td>${t}</td>`).join('')}</tr><tr><td>mm</td>${rs.map(r=>`<td>${r}</td>`).join('')}</tr></table></div></details>`;}
if(labType==='population'){const d=populationChange(val('births'),val('deaths'),val('incoming'),val('outgoing'));out.innerHTML=`<div class="metric-grid">${[["Loomulik iive",d.natural],["Rändesaldo",d.migration],["Kogumuutus",d.total]].map(([s,v])=>`<div class="metric"><strong>${v>0?'+':''}${v}</strong><span>${s}</span></div>`).join('')}</div><svg class="lab-chart" viewBox="0 0 550 240" role="img" aria-label="Nelja voo mõju rahvaarvu muutusele">${[["Sünnid",val('births'),'#8fae70'],["Surmad",val('deaths'),'#c99481'],["Saabumine",val('incoming'),'#7fabb1'],["Lahkumine",val('outgoing'),'#c9b279']].map(([s,v,c],i)=>`<text x="8" y="${35+i*50}" fill="#687867" font-size="12">${s}</text><rect x="90" y="${17+i*50}" width="${v/9}" height="27" rx="4" fill="${c}"/><text x="${100+v/9}" y="${36+i*50}" font-size="12" fill="#395a46">${v}</text>`).join('')}</svg><h3>Aasta lõpus: ${(100000+d.total).toLocaleString('ru-RU')} elanikku</h3><p class="caption">Muutus: ${(d.total/1000).toFixed(1)}%. Mudel ei prognoosi tulevast sündimust ega rännet.</p>`;}
if(labType==='energy'){const ss=['fossil','wind','solar','nuclear'].map(val),sum=ss.reduce((a,b)=>a+b),names=["Kütus","Tuul","Päike","Tuumaenergia"],colors=['#6b8270','#a1bd79','#e6c478','#7da7ac'];out.innerHTML=sum?`<div style="height:45px;display:flex;border-radius:9px;overflow:hidden;margin:30px 0">${ss.map((s,i)=>`<div style="width:${s/sum*100}%;background:${colors[i]}" title="${names[i]}: ${(s/sum*100).toFixed(1)}%"></div>`).join('')}</div><div class="table-wrap"><table>${ss.map((s,i)=>`<tr><td><span style="color:${colors[i]}">●</span> ${names[i]}</td><td>${(s/sum*100).toFixed(1)}%</td></tr>`).join('')}</table></div><div class="metric-grid"><div class="metric"><strong>${Math.round(energyMix(ss,[700,12,45,12]))}</strong><span>g CO₂-ekv/kWh</span></div><div class="metric"><strong>${Math.round((ss[1]+ss[2])/sum*100)}%</strong><span>muutlik tootmine</span></div><div class="metric"><strong>${Math.round(ss[0]/sum*100)}%</strong><span>fossiilenergia</span></div></div>`:"<div class=\"note\">Lisa vähemalt üks allikas: nulltoodangu korral ei ole bilanss määratud.</div>";}
if(labType==='water'){const r=val('rain')-val('evap')-val('use');out.innerHTML=`<div class="metric-grid"><div class="metric"><strong>${val('rain')}</strong><span>juurdevool, mm</span></div><div class="metric"><strong>${val('evap')+val('use')}</strong><span>kulu, mm</span></div><div class="metric"><strong>${r}</strong><span>jääk, mm</span></div></div><svg viewBox="0 0 550 210" class="lab-chart" role="img" aria-label="Veebilansi jäägi skeem"><rect x="70" y="20" width="400" height="170" rx="18" fill="#edf2e5"/><rect x="70" y="${190-Math.min(160,Math.max(0,r)*.2)}" width="400" height="${Math.min(160,Math.max(0,r)*.2)}" rx="18" fill="#94b8bf"/><text x="270" y="100" text-anchor="middle" fill="#315643" font-size="22">${r<0?"Puudujääk: varu väheneb":r===0?"Äravooluks jääki ei ole":"Vesi äravooluks: "+r+" mm"}</text></svg><p>${r<0?"Neid vooge ei saa lõputult säilitada: vähenda veevõttu ning kontrolli auramist ja taastumist.":"Kogu jääki ei saa võtta: ka jõgede ja ranniku ökosüsteemid vajavad vett."}</p>`;}
if(labType==='plates'){const type=$('#plate-type').value,s=val('plate-step')*.35;const desc={divergent:"Laamad lahknevad. Kerkiv sulamass tekitab uut ookeanilist maakoort. Näide: Kesk-Atlandi keskahelik.",convergent:"Ookeaniline laam sukeldub teise alla. Võivad tekkida süvik, maavärinad ja vulkaaniline kaar. Näide: Lõuna-Ameerika lääneosa.",transform:"Laamad nihkuvad piki piiri. Maakoor siin ei teki ega hävi; kogunev pinge võib vallanduda maavärinana. Pealtvaade, näide: San Andrease murrang."}[type];out.innerHTML=`<svg class="lab-chart" viewBox="0 0 550 270" role="img" aria-label="${E(desc)}"><rect x="15" y="130" width="520" height="100" rx="8" fill="#d5ae82"/><text x="275" y="250" font-size="12" text-anchor="middle" fill="#8b795e">${type==='transform'?"Pealtvaade · mõõtkavata skeem":"Astenosfäär · valdavalt tahke, plastne"}</text>${type==='divergent'?`<path d="M15 100H${267-s}v50H15z" fill="#8ca884"/><path d="M${283+s} 100H535v50H${283+s}z" fill="#65816a"/><path d="M${260-s} 170L275 90l${15+s} 80" fill="#db966d"/><text x="150" y="75" font-size="32" fill="#41634c">←</text><text x="355" y="75" font-size="32" fill="#41634c">→</text>`:type==='convergent'?`<path d="M15 105H270l${100+s} 96-25 15-90-68H15z" fill="#79938a"/><path d="M${280-s/3} 102H535v45H315z" fill="#adc08c"/><path d="M360 105l25-40 30 40" fill="#557657"/><text x="145" y="80" font-size="32" fill="#41634c">→</text><text x="430" y="80" font-size="32" fill="#41634c">←</text>`:`<rect x="20" y="${50-s}" width="250" height="150" fill="#8eac86"/><rect x="280" y="${50+s}" width="250" height="150" fill="#5f826d"/><text x="135" y="125" font-size="35" fill="white">↑</text><text x="395" y="125" font-size="35" fill="white">↓</text>`}</svg><div class="note">${desc}</div>`;}}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function render(){const [route='home',id]=(location.hash.slice(1)||'home').split('/');navRender(route);const pages={home,courses:()=>heading("ÕPPETEEKOND","Kolm geograafiakursust","Vali teema või liigu järjest. Õppetunnid, harjutused ja uurimistööd on omavahel seotud.")+`<div class="course-grid">${courses.map(courseCard).join('')}</div><div class="note">Telefonis on sõnastik, uurimistööd ja edenemine kättesaadavad ka siit: <a href="#glossary"><u>sõnastik</u></a> · <a href="#projects"><u>uurimistööd</u></a> · <a href="#progress"><u>edenemine</u></a>.</div>`,course:()=>coursePage(id),lesson:()=>lessonPage(id),practice:practicePage,quiz:quizPage,flash:flashPage,glossary:glossaryPage,projects:projectsPage,project:()=>projectPage(id),progress:progressPage,about:aboutPage,search:searchPage,atlas:atlasPage,labs:labsPage};$('#main').innerHTML=(pages[route]||missing)();if(route==='atlas')drawMap();if(route==='labs')labUpdate();document.title=`${({home:"Maailm muutub arusaadavamaks",lesson:lessons.find(l=>l.id===+id)?.title,course:courses.find(c=>c.id===+id)?.title,quiz:"Harjutamine",flash:"Mõistekaardid",about:"Õppekavast",project:projects[+id]?.title,search:"Otsing"}[route]||nav.find(n=>n[0]===route)?.[2]||"Uuri maailma")} — GEO`;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=+el.dataset.id,v=el.dataset.value;
if(a==='complete'){if(!state.done.includes(id)){state.done.push(id);activity(20);toast("Õppetund märgitud õpituks. +20 punkti");el.disabled=true;el.textContent="✓ Õppetund läbitud";}}
if(a==='lesson-answer'){const l=lessons.find(l=>l.id===id),ok=+v===0;$$('#lesson-check .answer').forEach(b=>{b.disabled=true;if(+b.dataset.value===0)b.classList.add('correct');});if(!ok)el.classList.add('wrong');$('#lesson-feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><strong>${ok?"Õige.":"Uurime lähemalt."}</strong> ${l.question.explanation}</div>`;state.answers++;if(ok)state.correct++;else if(!state.mistakes.includes(id))state.mistakes.push(id);activity(ok?5:0);}
if(a==='start-quiz')beginQuiz(+el.dataset.course);
if(a==='mistake-quiz')beginQuiz(0,true);
if(a==='capital-quiz'){quiz={title:"Riigid ja pealinnad",index:0,results:[],answered:false,items:shuffle(countries.filter(c=>!['IDN','ISR','XKX','ZAF','BOL','CHE'].includes(c.id))).slice(0,12).map(c=>({prompt:`Mis on riigi „${c.name}” pealinn?`,explanation:`${c.name} — ${c.capital}. ${countryNotes[c.id]||''}`,choices:shuffle([{s:c.capital,correct:true},...shuffle(countries.filter(x=>x.capital!==c.capital)).slice(0,3).map(x=>({s:x.capital,correct:false}))])}))};location.hash='quiz';render();}
if(a==='quiz-answer'&&quiz&&!quiz.answered){quiz.answered=true;const q=quiz.items[quiz.index],ok=q.choices[+v].correct;quiz.results.push({q,ok});state.answers++;if(ok){state.correct++;if(q.lesson)state.mistakes=state.mistakes.filter(i=>i!==q.lesson);}else if(q.lesson&&!state.mistakes.includes(q.lesson))state.mistakes.push(q.lesson);activity(ok?10:0);$$('.answer').forEach((b,i)=>{b.disabled=true;if(q.choices[i].correct)b.classList.add('correct');});if(!ok)el.classList.add('wrong');$('#quiz-feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><strong>${ok?"Õige! +10 punkti.":"See vastus ei ole õige."}</strong> ${q.explanation}</div><button class="btn" data-action="quiz-next">${quiz.index===quiz.items.length-1?"Vaata tulemust":"Järgmine küsimus"} →</button>`;}
if(a==='quiz-next'&&quiz?.answered){quiz.index++;quiz.answered=false;if(quiz.index===quiz.items.length){state.quizRuns++;activity();}render();}
if(a==='flash-start'){flash={queue:shuffle(terms).slice(0,12),flipped:false,known:0};location.hash='flash';render();}
if(a==='flash-flip'){flash.flipped=!flash.flipped;render();}
if(a==='flash-again'){flash.queue.push(flash.queue.shift());flash.flipped=false;render();}
if(a==='flash-known'){flash.queue.shift();flash.known++;flash.flipped=false;state.cards++;activity(5);render();}
if(a==='map-mode'){mapMode=v;if(v==='quiz')nextMap();render();}
if(a==='map-region'){mapRegion=v;if(mapMode==='quiz')nextMap();render();}
if(a==='map-next'){nextMap();render();}
if(a==='country-select'){mapSelected=el.dataset.id;$('#map-info').innerHTML=countryInfo(mapSelected);drawMap();}
if(a==='map-pick'){const c=countries.find(c=>c.id===el.dataset.id);if(mapMode==='explore'){if(c){mapSelected=c.id;$('#map-info').innerHTML=countryInfo(c.id);drawMap();}else toast("Seda territooriumi ei ole veel õppekaartides.");}else if(!mapAnswered){mapAnswered=true;document.querySelector('[data-action=map-next]').textContent="Järgmine →";const ok=el.dataset.id===mapTarget.id;if(ok){state.mapCorrect++;activity(10);}$('#map-feedback').textContent=ok?"Õige! +10 punkti. Jätka järgmise riigiga.":`See on ${c?.name||"teine territoorium"}. ${mapTarget.name} on esile tõstetud kuldse värviga. Vaata naabreid.`;$('#map-info').innerHTML=`<h3>${mapTarget.name}</h3><p>Pealinn: <strong>${mapTarget.capital}</strong></p><p class="caption">${countryNotes[mapTarget.id]||mapTarget.region}</p>`;drawMap();}}
if(a==='lab-tab'){labType=v;render();}
if(a==='lab-done'){if(!state.labs.includes(labType)){state.labs.push(labType);activity(15);toast("Katse märgitud. +15 punkti");}else toast("See labor on juba märgitud. Jätka tingimuste uurimist.");}
if(a==='download-project'){download('GEO-'+projects[id].title+'.txt',projects[id].title+'\n\n'+(state.notes['p'+id]||"Märkmeid ei ole veel lisatud."));}
if(a==='export')download('geo-progress.json',JSON.stringify(state,null,2),'application/json');
if(a==='reset')$('#reset-confirm').innerHTML="<div class=\"note\"><strong>Kas kustutada tulemused ja kõik märkmed sellest brauserist?</strong>Kui soovid neid säilitada, ekspordi esmalt koopia.<div class=\"action-row\"><button class=\"btn danger secondary\" data-action=\"reset-confirm\">Jah, kustuta</button><button class=\"btn secondary\" data-action=\"reset-cancel\">Tühista</button></div></div>";
if(a==='reset-cancel')$('#reset-confirm').innerHTML='';
if(a==='reset-confirm'){state=cleanProgress({});save();render();toast("Kohalik edenemine on kustutatud.");}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value.slice(0,20000);save();}if(el.id==='term-search')$('#term-results').innerHTML=termCards(terms.filter(t=>(t.ru+' '+t.et+' '+t.definition).toLocaleLowerCase().includes(el.value.trim().toLocaleLowerCase())));if(el.id==='country-search')$('#country-results').innerHTML=countryButtons(countries.filter(c=>c.name.toLocaleLowerCase().includes(el.value.toLocaleLowerCase())));if(el.id==='global-search'){const q=el.value.trim().toLocaleLowerCase().replace(/([а-яё]{4,})(ское|ская|ский|ские|ого|ому|ами|ями|ой|ый|ий|ая|ое|ые)$/u,(_,stem)=>stem);$('#search-results').innerHTML=q?lessons.filter(l=>(l.title+' '+l.et+' '+l.example+' '+l.paragraphs.join(' ')+' '+l.terms.map(t=>t.ru+' '+t.et).join(' ')).toLocaleLowerCase().includes(q)).map(lessonRow).join('')||"<p class=\"empty\">Midagi ei leitud. Proovi teist mõistet.</p>":"<p class=\"subtle\">Alusta otsingusõna sisestamist.</p>";}if(el.hasAttribute('data-lab-input'))labUpdate();});
document.addEventListener('change',async e=>{if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const parsed=JSON.parse(await f.text());if(parsed.version!==1||!Array.isArray(parsed.done))throw Error();if(!confirm("Kas asendada praegune edenemine ja märkmed faili andmetega?"))return;state=cleanProgress(parsed);save();render();toast("Edenemine imporditud.");}catch{toast("Koopia lugemine ebaõnnestus. Vaja on GEO eksporditud JSON-faili (kuni 2 MB).");}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [data-action]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();location.hash='search';setTimeout(()=>$('#global-search')?.focus(),0);}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
render();
